def generate(seed):
    r = random.Random(seed)
    while True:
        k = r.randint(3, 5)
        h = [r.randint(1, 15) for _ in range(k)]
        x = 0
        for v in h:
            x ^= v
        if x:
            return ' '.join(str(v) for v in h)

