def solve(clue):
    h = [int(x) for x in clue.split()]
    x = 0
    for v in h:
        x ^= v
    for i, v in enumerate(h):
        if v ^ x < v:
            h[i] = v ^ x
            break
    return ' '.join(str(v) for v in h)

